const { test } = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const vm = require('node:vm');
const crypto = require('node:crypto');
const acorn = require('acorn');
const root = path.join(__dirname, '..');
const read = file => fs.readFileSync(path.join(root, file), 'utf8');
const references = new Set(['gId', 'gN', 'gEBCN', 'getElementById', 'getElementsByName',
	'getElementsByClassName', 'querySelector', 'querySelectorAll', 'createElement',
	'getAttribute', 'setAttribute', 'addEventListener', 'removeEventListener',
	'openTab', 'openTabDirect', 'getItem', 'setItem', 'removeItem']);

function scripts(file, source) {
	return file.endsWith('.js') ? [source] : [...source.matchAll(/<script\b[^>]*>([\s\S]*?)<\/script>/gi)].map(m => m[1]);
}

function contract(file, source) {
	const found = [];
	function value(n) {
		if (n?.type === 'Literal') return n.value;
		if (n?.type === 'TemplateLiteral') return n.quasis.map(q => q.value.raw).join('${}');
	}
	function walk(n) {
		if (!n || typeof n !== 'object') return;
		if (n.type === 'CallExpression') {
			const name = n.callee.name || n.callee.property?.name;
			const argument = value(n.arguments[0]);
			if (references.has(name) && typeof argument === 'string') found.push([name, argument]);
		}
		for (const v of Object.values(n)) {
			if (Array.isArray(v)) v.forEach(walk);
			else if (v && typeof v === 'object') walk(v);
		}
	}
	for (const script of scripts(file, source)) walk(acorn.parse(script, { ecmaVersion: 'latest' }));
	return crypto.createHash('sha256').update(JSON.stringify(found)).digest('hex');
}

// Frozen against v16.0.1: translations must not change DOM selectors, events or storage keys.
const baseline = require('./zh-cn-contracts.json');
for (const [file, expected] of Object.entries(baseline)) {
	test(`中文界面保留原有选择器、事件和存储键：${file}`, () => {
		assert.equal(contract(file, read(file)), expected);
	});
}

const index = read('wled00/data/index.js');
const context = vm.createContext({});
vm.runInContext(index.slice(0, index.indexOf('// AI: end')), context);
test('所有内置灯效、参数和调色板均有中文显示', () => {
	const definitions = [...read('wled00/FX.cpp').matchAll(/_data_FX_\w+\[\]\s*PROGMEM\s*=\s*"(.*?)";/g)].map(m => m[1]);
	const labels = new Set();
	for (const definition of definitions) {
		const [name, parameters] = definition.split('@');
		labels.add(name);
		for (const section of (parameters || '').split(';').slice(0, 3)) {
			for (const label of section.split(',')) if (/[A-Za-z]/.test(label)) labels.add(label.trim());
		}
	}
	const palettes = read('wled00/FX_fcn.cpp').match(/JSON_palette_names\[\].*?R"=====\((.*?)\)====="/s)[1];
	JSON.parse(palettes).forEach(label => labels.add(label));
	for (const label of labels) assert.match(context.zhLabel(label), /[\u3400-\u9fff]/, label);
	assert.equal(context.zhLabel('我的自定义名称'), '我的自定义名称');
});

test('简化界面保留中文名称，同时移除能力图标', () => {
	const expression = index.match(/let selectedNameWithoutIcons = (.*);/)[1];
	const name = vm.runInNewContext(expression, { selectedName: '彩虹 🌈🎨▦♪' });
	assert.ok(name.startsWith('彩虹'));
	assert.ok(!/[🎨▦♪]/u.test(name));
});

test('设备网页声明简体中文与 UTF-8', () => {
	for (const file of Object.keys(baseline).filter(f => f.endsWith('.htm'))) {
		const source = read(file);
		if (!source.includes('<html')) continue;
		assert.match(source, /<html lang="zh-CN">/, file);
		assert.match(source, /<meta charset=["']?utf-8/i, file);
	}
});

